import { useMemo, useState } from "react";

import Sidebar from "../../components/Admin/Sidebar/sidebar";
import AdminHeader from "../../components/Admin/AdminHeader/AdminHeader";
import ProductTable from "../../components/Admin/ProductTable/ProductTable";

import "./produtos.css";

function Products() {
  const [searchTerm, setSearchTerm] = useState("");
  const [filter, setFilter] = useState("todos");

  const [products, setProducts] = useState([
    {
      id: 1,
      descricao: "Brinco Dourado",
      preco: "49.90",
      quantidade: 10,
      imagem: "",
    },
    {
      id: 2,
      descricao: "Colar Dourado",
      preco: "69.90",
      quantidade: 5,
      imagem: "",
    },
    {
      id: 3,
      descricao: "Pulseira Dourada",
      preco: "39.90",
      quantidade: 0,
      imagem: "",
    },
    {
      id: 4,
      descricao: "Anel Dourado",
      preco: "34.90",
      quantidade: 8,
      imagem: "",
    },
    {
      id: 5,
      descricao: "Brinco Pérola",
      preco: "54.90",
      quantidade: 3,
      imagem: "",
    },
  ]);

  const filteredProducts = useMemo(() => {
    return products.filter((product) => {
      const matchesSearch = product.descricao
        .toLowerCase()
        .includes(searchTerm.toLowerCase());

      if (filter === "disponiveis") {
        return matchesSearch && product.quantidade > 0;
      }

      if (filter === "indisponiveis") {
        return matchesSearch && product.quantidade === 0;
      }

      return matchesSearch;
    });
  }, [products, searchTerm, filter]);

  function handleEdit(product) {
    console.log("Editar produto:", product);
  }

  function handleDelete(id) {
    const confirmed = window.confirm(
      "Tem certeza que deseja excluir este produto?"
    );

    if (!confirmed) {
      return;
    }

    setProducts((currentProducts) =>
      currentProducts.filter(
        (product) => product.id !== id
      )
    );
  }

  return (
    <div className="admin-layout">

      <Sidebar />

      <div className="admin-main">

        <AdminHeader />

        <main className="products-page">

          <div className="products-page-header">

            <div>
              <p className="dashboard-eyebrow">
                GERENCIAMENTO
              </p>

              <h1>Produtos</h1>

              <p>
                Cadastre, edite e gerencie os produtos
                do catálogo.
              </p>
            </div>

            <button
              type="button"
              className="add-product-button"
            >
              + Adicionar produto
            </button>

          </div>

          <section className="products-content">

            <div className="products-controls">

              <div className="products-search">
                <label htmlFor="product-search">
                  Buscar produto
                </label>

                <input
                  id="product-search"
                  type="text"
                  value={searchTerm}
                  onChange={(event) =>
                    setSearchTerm(event.target.value)
                  }
                  placeholder="Digite o nome do produto..."
                />
              </div>

              <div className="products-filter">
                <label htmlFor="product-filter">
                  Status
                </label>

                <select
                  id="product-filter"
                  value={filter}
                  onChange={(event) =>
                    setFilter(event.target.value)
                  }
                >
                  <option value="todos">
                    Todos
                  </option>

                  <option value="disponiveis">
                    Disponíveis
                  </option>

                  <option value="indisponiveis">
                    Indisponíveis
                  </option>
                </select>
              </div>

            </div>

            <div className="products-count">
              {filteredProducts.length}{" "}
              {filteredProducts.length === 1
                ? "produto"
                : "produtos"}
            </div>

            <ProductTable
              products={filteredProducts}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />

          </section>

        </main>

      </div>

    </div>
  );
}

export default Products;
